files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: #1e293b;
  color: #e2e8f0;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 1rem;
}

.invoice-card {
  background: #0f172a;
  border-radius: 16px;
  padding: 2rem;
  width: 100%;
  max-width: 720px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  margin-bottom: 1.5rem;
  color: #f8fafc;
  letter-spacing: -0.02em;
}

.line-item {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  align-items: flex-end;
  margin-bottom: 1rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid #334155;
}

.line-item label {
  display: flex;
  flex-direction: column;
  font-size: 0.875rem;
  color: #94a3b8;
  gap: 0.25rem;
  flex: 1 1 120px;
}

.line-item .desc {
  flex: 2 1 200px;
}

.line-item input {
  background: #1e293b;
  border: 1px solid #334155;
  border-radius: 8px;
  padding: 0.5rem 0.75rem;
  color: #e2e8f0;
  font-size: 1rem;
  width: 100%;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.line-item input:focus {
  outline: none;
  border-color: #38bdf8;
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.25);
}

.line-total {
  font-weight: 600;
  color: #f8fafc;
  min-width: 80px;
  text-align: right;
  padding-bottom: 0.5rem;
  flex: 0 0 auto;
}

button {
  font-family: inherit;
  font-size: 1rem;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

button:active {
  transform: scale(0.97);
}

.remove-btn {
  background: transparent;
  color: #94a3b8;
  padding: 0.5rem 0.75rem;
  font-size: 1.25rem;
  line-height: 1;
  flex: 0 0 auto;
}

.remove-btn:hover {
  background: #334155;
  color: #f87171;
}

.remove-btn:focus-visible {
  outline: 2px solid #38bdf8;
  outline-offset: 2px;
}

#add-line {
  background: #334155;
  color: #e2e8f0;
  padding: 0.75rem 1.25rem;
  margin: 1rem 0 1.5rem;
  font-weight: 500;
}

#add-line:hover {
  background: #475569;
}

#add-line:focus-visible {
  outline: 2px solid #38bdf8;
  outline-offset: 2px;
}

.totals {
  border-top: 2px solid #334155;
  padding-top: 1.5rem;
}

.row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.5rem 0;
  font-size: 1rem;
}

.row label {
  color: #94a3b8;
}

.row input {
  background: #1e293b;
  border: 1px solid #334155;
  border-radius: 8px;
  padding: 0.5rem 0.75rem;
  color: #e2e8f0;
  font-size: 1rem;
  width: 100px;
  text-align: right;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.row input:focus {
  outline: none;
  border-color: #38bdf8;
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.25);
}

.grand {
  font-size: 1.25rem;
  font-weight: 700;
  color: #f8fafc;
  border-top: 1px solid #334155;
  margin-top: 0.5rem;
  padding-top: 1rem;
}

@media (max-width: 500px) {
  .invoice-card {
    padding: 1.25rem;
  }
  .line-item {
    flex-direction: column;
    align-items: stretch;
  }
  .line-total {
    text-align: left;
    padding-bottom: 0;
  }
  .remove-btn {
    align-self: flex-end;
  }
}

[hidden] {
  display: none !important;
}

document.addEventListener('DOMContentLoaded', () => {
  const container = document.getElementById('line-items-container');
  const addBtn = document.getElementById('add-line');
  const taxInput = document.getElementById('tax-rate');
  const subtotalEl = document.getElementById('subtotal');
  const taxEl = document.getElementById('tax');
  const grandEl = document.getElementById('grand-total');

  function createLineItem() {
    const div = document.createElement('div');
    div.className = 'line-item';
    div.innerHTML = `
      <label>Description <input type="text" class="desc" placeholder="Item description" aria-label="Description"></label>
      <label>Qty <input type="number" class="qty" min="1" value="1" step="1" aria-label="Quantity"></label>
      <label>Unit Price <input type="number" class="price" min="0" step="0.01" value="0.00" aria-label="Unit price"></label>
      <span class="line-total">$0.00</span>
      <button type="button" class="remove-btn" aria-label="Remove line item">✕</button>
    `;
    div.querySelector('.remove-btn').addEventListener('click', () => {
      div.remove();
      updateTotals();
    });
    div.querySelectorAll('input').forEach(input => {
      input.addEventListener('input', () => {
        updateLineTotal(div);
        updateTotals();
      });
    });
    return div;
  }

  function updateLineTotal(div) {
    const qty = parseFloat(div.querySelector('.qty').value) || 0;
    const price = parseFloat(div.querySelector('.price').value) || 0;
    const total = qty * price;
    div.querySelector('.line-total').textContent = '$' + total.toFixed(2);
  }

  function updateTotals() {
    let subtotal = 0;
    document.querySelectorAll('.line-item').forEach(div => {
      const qty = parseFloat(div.querySelector('.qty').value) || 0;
      const price = parseFloat(div.querySelector('.price').value) || 0;
      subtotal += qty * price;
    });
    const taxRate = parseFloat(taxInput.value) || 0;
    const tax = subtotal * (taxRate / 100);
    const grand = subtotal + tax;
    subtotalEl.textContent = '$' + subtotal.toFixed(2);
    taxEl.textContent = '$' + tax.toFixed(2);
    grandEl.textContent = '$' + grand.toFixed(2);
  }

  // Initialize first line item
  container.innerHTML = '';
  container.appendChild(createLineItem());

  addBtn.addEventListener('click', () => {
    container.appendChild(createLineItem());
    updateTotals();
  });

  taxInput.addEventListener('input', updateTotals);

  // Attach listeners to initial line item
  container.querySelectorAll('.line-item').forEach(div => {
    div.querySelectorAll('input').forEach(input => {
      input.addEventListener('input', () => {
        updateLineTotal(div);
        updateTotals();
      });
    });
    div.querySelector('.remove-btn').addEventListener('click', () => {
      div.remove();
      updateTotals();
    });
  });

  updateTotals();
});
